using System;
using System.IO;
using Microsoft.Build.Logging;
using Microsoft.Build.Framework;
using System.Collections.Generic;
using System.Linq;

var reader = new BinaryLogReplayEventSource();
var errors = new List<(string project, string code, string file, int line, string message)>();
var warnings = new List<(string project, string code, string file, int line, string message)>();
var failedProjects = new HashSet<string>();

reader.ErrorRaised += (sender, e) =>
{
    var proj = e.ProjectFile ?? "";
    errors.Add((proj, e.Code ?? "", e.File ?? "", e.LineNumber, e.Message ?? ""));
};

reader.WarningRaised += (sender, e) =>
{
    var proj = e.ProjectFile ?? "";
    warnings.Add((proj, e.Code ?? "", e.File ?? "", e.LineNumber, e.Message ?? ""));
};

reader.ProjectFinished += (sender, e) =>
{
    if (!e.Succeeded)
        failedProjects.Add(e.ProjectFile ?? "");
};

reader.Replay("build.binlog");

Console.WriteLine("=== FAILED PROJECTS ===");
foreach (var p in failedProjects.OrderBy(x => x))
    Console.WriteLine($"  {p}");

Console.WriteLine("\n=== ERRORS ===");
foreach (var e in errors)
    Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");

Console.WriteLine($"\n  Total errors: {errors.Count}");

if (warnings.Count > 0)
{
    Console.WriteLine("\n=== WARNINGS (first 20) ===");
    foreach (var w in warnings.Take(20))
        Console.WriteLine($"  [{w.code}] {w.file}({w.line}): {w.message}");
}

// Group errors by project
Console.WriteLine("\n=== ERRORS BY PROJECT ===");
foreach (var g in errors.GroupBy(e => e.project).OrderBy(g => g.Key))
{
    Console.WriteLine($"\n  Project: {g.Key}");
    foreach (var e in g)
        Console.WriteLine($"    [{e.code}] {e.file}({e.line}): {e.message}");
}
EOF
