// Find all projects and their dependencies
var projects = build.FindChildrenRecursive<Project>().ToList();
Console.WriteLine($"=== ALL PROJECTS ({projects.Count}) ===");
foreach (var p in projects)
    Console.WriteLine($"  {p.Name} | {p.ProjectFile}");

// Look for project references to understand dependency chain
Console.WriteLine("\n=== PROJECT REFERENCE ITEMS ===");
var items = build.FindChildrenRecursive<AddItem>().Where(i => i.Name == "ProjectReference").ToList();
foreach (var item in items)
{
    var proj = item.GetNearestParent<Project>();
    Console.WriteLine($"  {proj?.Name} references:");
    foreach (var child in item.Children)
        Console.WriteLine($"    -> {child}");
}

// Look for package references
Console.WriteLine("\n=== PACKAGE REFERENCES IN Services.csproj ===");
var svcProj = projects.FirstOrDefault(p => p.Name == "Services.csproj");
if (svcProj != null)
{
    var pkgRefs = svcProj.FindChildrenRecursive<AddItem>().Where(i => i.Name == "PackageReference").ToList();
    foreach (var item in pkgRefs)
    {
        foreach (var child in item.Children)
            Console.WriteLine($"  {child}");
    }
}
